            MRSCont.opts.fit.GAP.sum = [];
            MRSCont.opts.fit.GAP.diff1 = [];
            MRSCont.opts.fit.GAP.diff2 = [];
        else if ~isfield(MRSCont.opts.fit.GAP, 'sum')
                MRSCont.opts.fit.GAP.sum = [];
            end
            if ~isfield(MRSCont.opts.fit.GAP, 'diff1')
