% op_HadamardScans.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_addScans(in1,combMatrix);
% 
% DESCRIPTION:
% Add or subtract two scans together.
% 
% INPUTS:
% in        = Spectrum (in matlab structure format)
% combMatrix	 = How to combine the spectra
%
% OUTPUTS:
% out        = Result of adding inputs in1 and in2.  


function out=op_HadamardScans(in,combMatrix,name);

dim = in.dims.subSpecs;

if ~isempty(fieldnames(in))
    if dim == 2
        if length(combMatrix) == 2
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2);
        end
        if length(combMatrix) == 4
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2) + combMatrix(3)*in.fids(:,3)+ combMatrix(4)*in.fids(:,4);
        end
    end
end

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

out=in;
if ~contains(in.names,name)
        out.fids=cat(dim,in.fids,fids);
        out.specs=cat(dim,in.specs,specs);
        out.sz=size(fids);            
        out.names{end+1} = name;
        out.subspecs = out.subspecs + 1;
    else
        ind = find(strcmp(out.names,name));
        out.fids(:,ind,:,:,:,:,:) = fids(:,1,:,:,:,:,:);
        out.specs(:,ind,:,:,:,:,:) = specs(:,1,:,:,:,:,:);
end




% op_mergesubspec.m
% Helge Zoellner, Johns Hopkins University 2021.
% 
% USAGE:
% out=op_mergesubspec(varargin);
% 
% DESCRIPTION:
% Merges input structs into the subspectra dimension
% 
% INPUTS:
% varargin     = input data in matlab structure format.
%
% OUTPUTS:
% out    = Output dataset with merged subspectra

function out=op_mergesubspec(varargin);
in1 = varargin{1};

if isempty(varargin{2}) %Check if the first argument to be a null string
    error('You have to at least put in two structs')
else

    for ss = 2 : length(varargin)
        in2 = varargin{ss};
        if in1.dims.subSpecs~=0 && in2.dims.subSpecs~=0 && in1.dims.subSpecs ~= in2.dims.subSpecs
            %RULE:  Averages dimension must be the same for both inputs UNLESS one of
            %the inputs has an averages dimension of zero:
            error('subspectra dimensions must be the same for both inputs');
        end

        if in1.dims.subSpecs==0 && in2.dims.subSpecs==0
            dim=2;
        elseif in1.dims.subSpecs==0
            dim=in2.dims.subSpecs;
        elseif in2.dims.averages==0;
            dim=in1.dims.subSpecs;
        else
            dim=in1.dims.subSpecs;
        end
        if ~contains(in1.names,in2.names(1))
            in1.fids=cat(dim,in1.fids,in2.fids);
            in1.specs=cat(dim,in1.specs,in2.specs);
            in1.subspecs=in1.subspecs+in2.subspecs;
            in1.names{end+1} = in2.names{1};
        else
            ind = find(strcmp(in1.names,in2.names(1)));
            in1.fids(:,ind,:,:,:,:,:) = in2.fids(:,1,:,:,:,:,:);
            in1.specs(:,ind,:,:,:,:,:) = in2.specs(:,1,:,:,:,:,:);
        end

    end
    sz=size(in1.fids);

    %FILLING IN DATA STRUCTURE
    out=in1;
    out.sz=sz;
%     out.rawAverages=in1.rawAverages+in2.rawAverages;
    if in1.dims.subSpecs==0
        out.dims.subSpecs=dim;
    end


    %FILLING IN THE FLAGS
    out.flags=in1.flags;
    out.flags.writtentostruct=1;
end
% op_combinesubspecs.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_combinesubspecs(in,mode);
% 
% DESCRIPTION:
% Combine the subspectra in an acquisition either by addition or
% subtraction.
% 
% INPUTS:
% in        = input data in matlab structure format.
% mode      = -"diff" adds the subspectra together (this is counter intuitive,
%             but the reason is that many "difference editing" sequences use phase
%             cycling of the readout ADC to achieve "subtraction by addition".
%             -"summ" performs a subtraction of the subspectra.
%
% OUTPUTS:
% out       = Output following combination of subspectra.  

function out=op_combinesubspecs(in,mode);

if in.flags.subtracted
    error('ERROR:  Subspectra have already been combined!  Aborting!');
end
if in.flags.isFourSteps
    error('ERROR: data with four steps must first be converted using op_fourStepCombine.m!  Aborting!');
end

% if ~in.flags.freqcorrected
%     disp('WARNING:  Frequency correction has not yet been performed!');
% end
% if ~in.flags.phasecorrected
%     disp('WARNING:  Phase correction has not yet been performed!');
% end


if mode=='diff'
    %add the spectrum along the subSpecs dimension;
    fids=sum(in.fids,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by number of subspecs so that this is an averaging operation;
elseif mode=='summ'
    %subtract the spectrum along the subSpecs dimension;
    fids=diff(in.fids,1,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by nymber of subspecs so that this is an averaging operation;
end

fids=squeeze(fids);

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

%change the dims variables
if in.dims.t>in.dims.subSpecs
    dims.t=in.dims.t-1;
else
    dims.t=in.dims.t;
end
if in.dims.coils>in.dims.subSpecs
    dims.coils=in.dims.coils-1;
else
    dims.coils=in.dims.coils;
end
if in.dims.averages>in.dims.subSpecs
    dims.averages=in.dims.averages-1;
else
    dims.averages=in.dims.averages;
end
dims.subSpecs=0;
if in.dims.extras>in.dims.subSpecs
    dims.extras=in.dims.extras-1;
else
    dims.extras=in.dims.extras;
end

%re-calculate the sz variable
sz=size(fids);


%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.dims=dims;
out.subspecs=1;
out.averages=in.averages/2;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.subtracted=1;

